/* rail.js: the skills page's margin rail (skills/, generated by scripts/build_site_skills.py).
   A narrow column of hexagons in the right margin fills from the top as the reader scrolls
   down the page: each hexagon arrives in a gas-flame colour and cools to white, like the
   home page wordmark. It is scroll-linked only, so it never moves on its own and needs no pause
   control. CSS hides it on narrow screens. draw() is the only canvas code. */
(function () {
  'use strict';
  var canvas = document.querySelector('canvas.hex-rail');
  if (!canvas) return;
  var ctx = canvas.getContext('2d');

  var COLS = 2;          /* hexagons across the rail */
  var SPREAD = 0.14;     /* how ragged the filling edge is, as a share of the scroll */
  var COOL = 0.07;       /* share of the scroll over which a lit hexagon cools to white */

  function hash(x, y) { var h = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return h - Math.floor(h); }
  function noise(x, y) {
    var x0 = Math.floor(x), y0 = Math.floor(y), fx = x - x0, fy = y - y0;
    var sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);
    var a = hash(x0, y0), b = hash(x0 + 1, y0), c = hash(x0, y0 + 1), d = hash(x0 + 1, y0 + 1);
    var top = a + (b - a) * sx, bottom = c + (d - c) * sx;
    return top + (bottom - top) * sy;
  }
  function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

  var cells = [], R = 0, dpr = 1, w = 0, h = 0;

  /* Lay out a pointy-top honeycomb that fills the rail; each cell gets a threshold in [0, 1]
     from its row plus clustered noise, so the filling edge is uneven. */
  function layout() {
    w = canvas.clientWidth; h = canvas.clientHeight; dpr = window.devicePixelRatio || 1;
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
    var cellW = w / (COLS + 0.5);
    R = cellW / Math.sqrt(3);
    var dy = 1.5 * R, rows = Math.max(2, Math.floor((h - 2 * R) / dy) + 1);
    cells = [];
    for (var r = 0; r < rows; r++) {
      for (var c = 0; c < COLS; c++) {
        var t = (r / (rows - 1)) * (1 - SPREAD) + (noise(c / 2, r / 3) * 0.8 + hash(c, r) * 0.2) * SPREAD;
        cells.push({ x: cellW * (c + 0.5 + (r % 2 ? 0.5 : 0)), y: R + r * dy, c: c, r: r, t: t });
      }
    }
  }

  /* How far the reader is through the page: 0 at the top, 1 at the very bottom, so the rail
     finishes exactly when the page does (the footer included). */
  function progress() {
    var max = document.documentElement.scrollHeight - window.innerHeight;
    return max > 0 ? clamp(window.scrollY / max, 0, 1) : 1;
  }

  function flame(q, cool) {
    var hue = 192 + noise(q.c / 3, q.r / 6) * 78;
    var m = noise(q.c / 2 + 30, q.r / 3);
    var light = 50 + m * 38;
    light += (100 - light) * cool;
    var sat = (95 - m * 25) * (1 - cool);
    return 'hsl(' + hue.toFixed(1) + ' ' + sat.toFixed(1) + '% ' + light.toFixed(1) + '%)';
  }

  function hexPath(x, y, rad) {
    ctx.beginPath();
    for (var i = 0; i < 6; i++) {
      var a = Math.PI / 180 * (60 * i - 30);
      if (i) ctx.lineTo(x + Math.cos(a) * rad, y + Math.sin(a) * rad); else ctx.moveTo(x + Math.cos(a) * rad, y + Math.sin(a) * rad);
    }
    ctx.closePath();
  }

  function draw() {
    var plan = getComputedStyle(document.documentElement).getPropertyValue('--wm-plan').trim();
    /* The filling edge reaches the last row exactly at the bottom of the page. */
    var p = progress();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    ctx.globalAlpha = 1;
    for (var i = 0; i < cells.length; i++) {
      var q = cells[i];
      /* Quiet by design: unfilled cells are faint, settled cells a soft white, and flame colour
         shows only along the filling edge while a cell cools. */
      var cool = clamp((p - q.t) / COOL, 0, 1);
      if (p < q.t) { ctx.globalAlpha = 0.45; ctx.fillStyle = plan; }
      else { ctx.globalAlpha = 0.85 - 0.6 * cool; ctx.fillStyle = flame(q, cool); }
      hexPath(q.x, q.y, R * 0.88);
      ctx.fill();
    }
  }

  var queued = false;
  function schedule() {
    if (queued) return;
    queued = true;
    window.requestAnimationFrame(function () { queued = false; draw(); });
  }
  function refresh() { if (canvas.clientWidth) { layout(); draw(); } }

  window.addEventListener('scroll', schedule, { passive: true });
  window.addEventListener('resize', refresh);
  if ('ResizeObserver' in window) new ResizeObserver(refresh).observe(canvas);
  refresh();
})();
